#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses OpenMP; correct under any thread count.
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    // Basic size handling
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build CSR (compressed sparse row) from COO to enable safe parallel SpMV.
    // Also build CSC-like access for A^T via CSR of transposed entries (needed for CG).
    const size_t nnz = A.size();

    std::vector<size_t> rowPtr(N + 1, 0), colIdx(nnz);
    std::vector<double> val(nnz);

    // Count nnz per row
    for (size_t k = 0; k < nnz; ++k) {
        if (A[k].row < N) rowPtr[A[k].row + 1]++;
    }
    // Prefix sum
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] += rowPtr[i];

    // Fill CSR using row offsets
    std::vector<size_t> next = rowPtr;
    for (size_t k = 0; k < nnz; ++k) {
        const size_t r = A[k].row;
        if (r >= N) continue;
        const size_t p = next[r]++;
        colIdx[p] = A[k].column;
        val[p]    = A[k].value;
    }

    // Also build CSR for A^T (transpose) for applying A^T (for normal equations CG if needed).
    std::vector<size_t> rowPtrT(N + 1, 0), colIdxT(nnz);
    std::vector<double> valT(nnz);
    for (size_t k = 0; k < nnz; ++k) {
        if (A[k].column < N) rowPtrT[A[k].column + 1]++;
    }
    for (size_t i = 0; i < N; ++i) rowPtrT[i + 1] += rowPtrT[i];
    std::vector<size_t> nextT = rowPtrT;
    for (size_t k = 0; k < nnz; ++k) {
        const size_t rT = A[k].column;
        if (rT >= N) continue;
        const size_t p = nextT[rT]++;
        colIdxT[p] = A[k].row;
        valT[p]    = A[k].value;
    }

    auto spmv_csr = [&](const std::vector<size_t>& rp,
                        const std::vector<size_t>& ci,
                        const std::vector<double>& vv,
                        const std::vector<double>& in,
                        std::vector<double>& out)
    {
        out.assign(N, 0.0);
        #pragma omp parallel for schedule(static)
        for (long long i_ll = 0; i_ll < (long long)N; ++i_ll) {
            const size_t i = (size_t)i_ll;
            double sum = 0.0;
            for (size_t p = rp[i]; p < rp[i + 1]; ++p) {
                const size_t j = ci[p];
                if (j < N) sum += vv[p] * in[j];
            }
            out[i] = sum; // each i written by a single thread
        }
    };

    auto dot = [&](const std::vector<double>& u, const std::vector<double>& v) -> double {
        double s = 0.0;
        #pragma omp parallel for reduction(+:s) schedule(static)
        for (long long i_ll = 0; i_ll < (long long)N; ++i_ll) {
            const size_t i = (size_t)i_ll;
            s += u[i] * v[i];
        }
        return s;
    };

    auto axpy = [&](double a, const std::vector<double>& u, std::vector<double>& v) {
        #pragma omp parallel for schedule(static)
        for (long long i_ll = 0; i_ll < (long long)N; ++i_ll) {
            const size_t i = (size_t)i_ll;
            v[i] += a * u[i];
        }
    };

    auto xpay = [&](std::vector<double>& y, double a, const std::vector<double>& x_in) {
        // y = x_in + a*y
        #pragma omp parallel for schedule(static)
        for (long long i_ll = 0; i_ll < (long long)N; ++i_ll) {
            const size_t i = (size_t)i_ll;
            y[i] = x_in[i] + a * y[i];
        }
    };

    auto scal = [&](double a, std::vector<double>& v) {
        #pragma omp parallel for schedule(static)
        for (long long i_ll = 0; i_ll < (long long)N; ++i_ll) {
            const size_t i = (size_t)i_ll;
            v[i] *= a;
        }
    };

    // We solve via Conjugate Gradient on normal equations: (A^T A) x = A^T b
    // This works for general A (including the example), though it targets least-squares if inconsistent.
    // For SPD A it still converges (often slower than CG on A directly, but robust here).
    std::vector<double> Atb(N, 0.0), tmp(N, 0.0);
    spmv_csr(rowPtrT, colIdxT, valT, b, Atb); // Atb = A^T b

    // Define operator M(x) = A^T (A x)
    auto apply_M = [&](const std::vector<double>& in, std::vector<double>& out) {
        spmv_csr(rowPtr,  colIdx,  val,  in,  tmp); // tmp = A in
        spmv_csr(rowPtrT, colIdxT, valT, tmp, out); // out = A^T tmp
    };

    // CG iterations
    const double tol = 1e-12;
    const int maxIters = (int)std::max<size_t>(100, 10 * N);

    std::vector<double> r(N, 0.0), p(N, 0.0), Mp(N, 0.0), Mx(N, 0.0);

    // r = Atb - Mx (x starts at 0, so r = Atb)
    r = Atb;
    p = r;

    double rr = dot(r, r);
    const double rr0 = rr;
    if (rr0 == 0.0) {
        // b is in nullspace (or zero); x=0 satisfies normal equations
        return;
    }

    for (int it = 0; it < maxIters; ++it) {
        apply_M(p, Mp);

        const double pMp = dot(p, Mp);
        if (pMp == 0.0) break;

        const double alpha = rr / pMp;

        // x = x + alpha * p
        axpy(alpha, p, x);

        // r = r - alpha * Mp
        axpy(-alpha, Mp, r);

        const double rr_new = dot(r, r);
        if (rr_new <= tol * tol * rr0) break;

        const double beta = rr_new / rr;

        // p = r + beta * p
        // reuse p: p = beta*p; p += r
        scal(beta, p);
        axpy(1.0, r, p);

        rr = rr_new;
    }
}
